# November 19, 2026: the City of Albany (region alb), drawn at random by tools/choose.py --state ny. The Atlas's 44
# Albany places were almost all vanished sites from the first catalogue, so this batch takes what still stands and is
# worth going to see: the city's two oldest buildings, the derelict churches and bath house on Historic Albany
# Foundation's "Places in Peril" list, the old Erie Canal Lock One dug up again in August 2026, and the downtown
# churches, museum and theatre with their original glass, carving and painting. Sources were opened in this session:
# Wikipedia as raw text (tools/wiki_raw.py) and, through tools/page.py, Historic Albany Foundation's 2024 "Places in
# Peril" page and its 2026 event page for 48 Hudson Avenue, WAMC and Spectrum News reports, the Evangelist, HMdb, the
# churches' and the Albany Institute's own pages, the Hudson River Valley heritage-area page and the Albany Heritage
# Area walking-tour brochure (PDF, text layer read).
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
BATCH={'key':'alb_ndxn','label':'Albany: oldest houses, derelict churches and downtown landmarks','added':'2026-11-19 00:40'}
